func accumulateBatchOutcome(res *TransmuteResult, b batchOutcome, lastBatchErr *error) {
	if res == nil {
		return
	}
	res.Scanned += b.scanned
	res.Inserted += b.inserted
	res.Updated += b.updated
	res.Deleted += b.deleted
	res.Skipped += b.skipped
	res.OccSkipped += b.occSkipped
	res.RuleMisses += b.ruleMisses
	res.TypeErrors += b.typeErrors
	if b.lastErr != nil && lastBatchErr != nil && *lastBatchErr == nil {
		*lastBatchErr = b.lastErr
	}
}

